// accessLine queues the one local line of a request, http.server.request.completed:
// INFO for a normal status, WARN for 400 to 499, ERROR for 500 or higher and for a
// handler that panicked (status 0). It holds the method, the route pattern, the
// status, the error type and the duration, and never a path, query, header or body.
func (r *Runtime) accessLine(ctx context.Context, start, end time.Time, method, route string, status int) {
	if r.service.local == nil {
		return
	}
	duration := end.Sub(start).Seconds()
	local := localRecord{Time: end, Service: r.service.service, Instance: r.instance, Severity: "INFO", Event: "http.server.request.completed", Message: "HTTP request completed", HTTPMethod: method, HTTPRoute: route, HTTPStatus: status, DurationSeconds: &duration}
	switch {
	case status == 0:
		local.Severity, local.ErrorType = "ERROR", "panic"
	case status >= 500:
		local.Severity, local.ErrorType = "ERROR", strconv.Itoa(status)
	case status >= 400:
		local.Severity = "WARN"
	}
	if sc := trace.SpanContextFromContext(ctx); sc.IsValid() {
		local.TraceID = sc.TraceID().String()
		local.SpanID = sc.SpanID().String()
	}
	r.service.mu.Lock()
	defer r.service.mu.Unlock()
	if !r.closed.Load() && r.admitAccess(accessBudget{event: local.Event, name: route, status: strconv.Itoa(status), severity: local.Severity}, end) {
		r.service.local.enqueue(local)
	}
}

// admitAccess closes the windows that ended and tells whether the budget of key
// takes one more line. An INFO line is always taken. The caller holds service.mu.
func (r *Runtime) admitAccess(key accessBudget, at time.Time) bool {
	r.closeAccessWindows(false)
	if key.severity == "INFO" {
		return true
	}
	if r.service.windows == nil {
		r.service.windows = map[accessBudget]*accessWindow{}
	}
	w := r.service.windows[key]
	if w == nil {
		if len(r.service.windows) >= accessBudgets {
			r.service.local.dropped.Add(1)
			return false
		}
		w = &accessWindow{start: r.accessNow()}
		r.service.windows[key] = w
	}
	if w.written >= AccessLimit {
		w.dropped++
		return false
	}
	w.written++
	return true
}
func (r *Runtime) accessNow() time.Time {
	if r.service.now != nil {
		return r.service.now()
	}
	return time.Now()
}

// closeAccessWindows ends each window that ended by the clock, or each window
// when all is true, and queues one line with the count of the dropped lines of
// each that dropped lines. The caller holds service.mu.
func (r *Runtime) closeAccessWindows(all bool) {
	if len(r.service.windows) == 0 || r.service.local == nil {
		return
	}
	now := r.accessNow()
	for key, w := range r.service.windows {
		if !all && now.Sub(w.start) < AccessWindow {
			continue
		}
		if w.dropped > 0 {
			local := localRecord{Time: now, Service: r.service.service, Instance: r.instance, Severity: key.severity, Event: key.event, Message: "the local log dropped lines of this route or method and status in the last window", Dropped: w.dropped}
			status, _ := strconv.Atoi(key.status)
			if key.event == "rpc.server.call.completed" {
				local.RPCMethod, local.RPCStatus = key.name, key.status
			} else {
				local.HTTPRoute, local.HTTPStatus = key.name, status
			}
			r.service.local.enqueue(local)
		}
		delete(r.service.windows, key)
	}
}

// rpcLine queues the one local line of a gRPC call, rpc.server.call.completed:
// INFO for OK, ERROR for a server failure code and WARN for every other code.
func (r *Runtime) rpcLine(ctx context.Context, start, end time.Time, method, value string, code grpccodes.Code) {
	if r.service.local == nil {
		return
	}
	duration := end.Sub(start).Seconds()
	local := localRecord{Time: end, Service: r.service.service, Instance: r.instance, Severity: "WARN", Event: "rpc.server.call.completed", Message: "RPC call completed", RPCMethod: method, RPCStatus: value, DurationSeconds: &duration}
	switch code {
	case grpccodes.OK:
		local.Severity = "INFO"
	case grpccodes.Unknown, grpccodes.DeadlineExceeded, grpccodes.Unimplemented, grpccodes.Internal, grpccodes.Unavailable, grpccodes.DataLoss:
		local.Severity, local.ErrorType = "ERROR", value
	}
	if sc := trace.SpanContextFromContext(ctx); sc.IsValid() {
		local.TraceID = sc.TraceID().String()
		local.SpanID = sc.SpanID().String()
	}
	r.service.mu.Lock()
	defer r.service.mu.Unlock()
	if !r.closed.Load() && r.admitAccess(accessBudget{event: local.Event, name: method, status: value, severity: local.Severity}, end) {
		r.service.local.enqueue(local)
	}
}

type httpObservationKey struct{}
type httpObservation struct{ route atomic.Pointer[string] }

func safeRoute(pattern string) string {
	if pattern == "" || pattern == "/" || len(pattern) > 256 {
		return ""
	}
	_, route, hasMethod := strings.Cut(pattern, " ")
	if !hasMethod {
		route = pattern
	}
	if strings.HasPrefix(route, "/") && strings.Trim(route, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/._-{}$") == "" {
		return route
	}
	return ""
}
func recordRoute(span trace.Span, method, pattern string) {
	if route := safeRoute(pattern); route != "" {
		span.SetName(method + " " + route)
		span.SetAttributes(attribute.String("http.route", route))
	}
}

// TraceRPC starts a span for a registered gRPC method. The generated transport
// calls finish once, with its final status, after authentication and execution.
// A stream span ends when the transport ends the stream, including expiry.
func (r *Runtime) TraceRPC(ctx context.Context, fullMethod string) (context.Context, func(error)) {
	if r.closed.Load() {
		return ctx, func(error) {}
	}
	ctx = r.Context(ctx)
	method := strings.TrimPrefix(fullMethod, "/")
	service, name, found := strings.Cut(method, "/")
	if !strings.HasPrefix(fullMethod, "/") || !found || service == "" || name == "" || len(method) > 256 || strings.Contains(name, "/") || strings.Trim(service, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._") != "" || strings.Trim(name, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_") != "" {
		method = "_OTHER"
	}
	if r.provider == nil {
		start := time.Now()
		var once sync.Once
		return ctx, func(err error) {
			once.Do(func() { code, value := rpcStatus(err); r.rpcLine(ctx, start, time.Now(), method, value, code) })
		}
	}
	md, _ := metadata.FromIncomingContext(ctx)
	values := md.Get("traceparent")
	if len(values) == 1 && len(values[0]) == 55 {
		ctx = (propagation.TraceContext{}).Extract(ctx, propagation.MapCarrier{"traceparent": values[0]})
	}
	tracer := r.grpcTracer
	if tracer == nil {
		tracer = r.provider.Tracer("stego/grpc")
	}
	start := time.Now()
	ctx, span := tracer.Start(ctx, method, trace.WithSpanKind(trace.SpanKindServer), trace.WithAttributes(attribute.String("rpc.system.name", "grpc"), attribute.String("rpc.method", method)), trace.WithTimestamp(start))
	r.signals.rpcStarted(ctx)
	return ctx, func(err error) {
		end := time.Now()
		code, value := rpcStatus(err)
		span.SetAttributes(attribute.String("rpc.response.status_code", value))
		switch code {
		case grpccodes.Unknown, grpccodes.DeadlineExceeded, grpccodes.Unimplemented, grpccodes.Internal, grpccodes.Unavailable, grpccodes.DataLoss:
			span.SetStatus(codes.Error, "")
			span.SetAttributes(attribute.String("error.type", value))
		}
		r.signals.rpcFinished(ctx, start, end, method, value, code)
		r.rpcLine(ctx, start, end, method, value, code)
		span.End(trace.WithTimestamp(end))
	}
}

// rpcStatus gives the code of err and its fixed name; an unknown code is UNKNOWN.
func rpcStatus(err error) (grpccodes.Code, string) {
	code := status.Code(err)
	names := [...]string{"OK", "CANCELLED", "UNKNOWN", "INVALID_ARGUMENT", "DEADLINE_EXCEEDED", "NOT_FOUND", "ALREADY_EXISTS", "PERMISSION_DENIED", "RESOURCE_EXHAUSTED", "FAILED_PRECONDITION", "ABORTED", "OUT_OF_RANGE", "UNIMPLEMENTED", "INTERNAL", "UNAVAILABLE", "DATA_LOSS", "UNAUTHENTICATED"}
	if int64(code) >= int64(len(names)) {
		code = grpccodes.Unknown
	}
	return code, names[code]
}
